/**
 * Runtime context the clerk must load before it touches PayPal.
 *
 * The PayPal TypeScript Server SDK is generated by APIMatic. This pack is the
 * same idea as APIMatic's Context Plugin, moved from coding time to decision
 * time: the agent may call only the methods listed here, and only with amounts
 * the shop policy has already signed.
 */
export const PAYPAL_CONTEXT = {
  source: "PayPal Server SDK 2.x (APIMatic-generated) + Invoicing v2 REST",
  rule: "The model never chooses an amount. Policy signs the price. PayPal only sees that amount.",
  methods: [
    {
      id: "orders.create",
      sdk: "OrdersController.createOrder",
      intent: "AUTHORIZE",
      use: "Open a deposit authorization for the policy-signed deposit. Not the full price.",
    },
    {
      id: "orders.authorize",
      sdk: "OrdersController.authorizeOrder",
      use: "After the buyer approves, place the deposit on hold.",
    },
    {
      id: "payments.capture",
      sdk: "PaymentsController.captureAuthorizedPayment",
      use: "Capture the authorization only once the van is loaded.",
    },
    {
      id: "payments.refund",
      sdk: "PaymentsController.refundCapturedPayment",
      use: "Partial refund of a captured payment. Never refund an unpaid hold.",
    },
    {
      id: "invoicing.create",
      sdk: "POST /v2/invoicing/invoices",
      use: "Invoice the balance, due on delivery. Separate from the deposit.",
    },
  ],
} as const;

export function contextSummary() {
  return PAYPAL_CONTEXT.methods.map((method) => method.sdk).join(", ");
}
